#include <stdio.h>
#include <stdlib.h>
#include <math.h>

long long reachNumber(long long target) {
    if (target < 0) target = -target;
    long long k = (long long)((sqrtl(1.0L + 8.0L * target) - 1.0L) / 2.0L);
    while (k * (k + 1) / 2 < target) ++k;
    while (k > 0 && (k - 1) * k / 2 >= target) --k;
    long long total = k * (k + 1) / 2;
    if ((total - target) % 2 == 0) return k;
    return k + 1 + (k & 1LL);
}

