        long k = (long)((Math.sqrt(1.0 + 8.0 * target) - 1.0) / 2.0);
        while (k * (k + 1) / 2 < target) k++;
        while (k > 0 && (k - 1) * k / 2 >= target) k--;
        long total = k * (k + 1) / 2;
        if ((total - target) % 2 == 0) return (int)k;
        return (int)(k + 1 + (k & 1L));
    }
}

